      renwu = "npc",
      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      ruchang = -1,
      sentence = "I couldn't think of anything that'll surprise you, but I wasn't about to let it turn into another ordinary birthday either.",
