      renwu = "npc",
      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      ruchang = 9,
      sentence = "So, I figured I'd do something a little more traditional. That will also make it kind of \"special.\"",
      voice = 1,
      next = {100209}
    },
    [100209] = {
      beijing = 1671,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      sentence = "The noodles in the bowl were pearly white. Although a little uneven in thickness, I could still tell that whoever made it put a lot of effort into it.",
      next = {100210}
    },
    [100210] = {
      beijing = 1671,
      dhead = 111,
      dialog = 1,
      music = "24_Romantic_Quiet",
      renming = "$u",
      renwu = "npc",
      sentence = "You cooked this yourself?",
