      renming = "Lucien",
      renwu = "npc",
      role1 = 235000,
      role2 = 201105,
      role3 = 201201,
      role5 = 235404,
      ruchang = -1,
      sentence = "Yes. I heard Longevity Noodles must be cooked with one long and unbroken strip of noodle. It's supposed to signify a long-lasting life. Although the presentation is a bit lacking, I'm sure it'll taste just fine.",
