      renwu = "npc",
      role1 = 337000,
      role2 = 301106,
      role3 = 301201,
      sentence = "He placed a pointy party hat on my head. The gentle glow of the candle reflected off of his beautiful eyes. I stared at him, unwilling to look away.",
